#!/usr/bin/env node
/**
 * Playwright script to retrieve ngrok authtoken from dashboard.
 * Launches browser in headed mode for user login, then extracts token.
 *
 * Usage: npx playwright test --headed docker/scripts/get-ngrok-token.mjs
 * Or:    node docker/scripts/get-ngrok-token.mjs
 */

import { chromium } from 'playwright';
import { writeFileSync, existsSync, readFileSync } from 'fs';
import { join, dirname } from 'path';
import { fileURLToPath } from 'url';

const __dirname = dirname(fileURLToPath(import.meta.url));
const ENV_PATH = join(__dirname, '..', '.env');

async function main() {
  console.log('🚀 Launching browser to retrieve ngrok authtoken...');
  console.log('   Please log in to your ngrok account if prompted.\n');

  const browser = await chromium.launch({
    headless: false,
    slowMo: 100
  });

  const context = await browser.newContext();
  const page = await context.newPage();

  try {
    // Navigate to ngrok authtoken page
    await page.goto('https://dashboard.ngrok.com/get-started/your-authtoken');

    // Wait for either login redirect or token page
    console.log('⏳ Waiting for login or token page...');

    // If redirected to login, wait for user to complete
    if (page.url().includes('login') || page.url().includes('auth')) {
      console.log('🔐 Login required. Please log in to ngrok...');
      // Wait for navigation back to dashboard after login
      await page.waitForURL('**/dashboard.ngrok.com/**', { timeout: 300000 }); // 5 min timeout
      // Navigate to token page after login
      await page.goto('https://dashboard.ngrok.com/get-started/your-authtoken');
    }

    // Wait for the token element to appear
    console.log('🔍 Looking for authtoken...');

    // The token is typically in a code/pre element or input field
    // Try multiple selectors
    let token = null;

    // Wait for page to load
    await page.waitForLoadState('networkidle');

    // Try to find token - ngrok dashboard shows it in a copyable field
    const tokenSelectors = [
      'input[type="text"][value*="2"]', // Token usually starts with "2"
      '[data-testid="authtoken"]',
      '.authtoken',
      'code:has-text("2")',
      'pre:has-text("2")'
    ];

    for (const selector of tokenSelectors) {
      try {
        const element = await page.$(selector);
        if (element) {
          token = await element.getAttribute('value') || await element.textContent();
          if (token && token.length > 20) {
            break;
          }
        }
      } catch (e) {
        // Try next selector
      }
    }

    // If selectors failed, try to find via page content
    if (!token) {
      console.log('🔄 Trying alternative extraction method...');
      const content = await page.content();
      // ngrok tokens are typically long alphanumeric strings starting with "2"
      const tokenMatch = content.match(/2[a-zA-Z0-9_-]{40,}/);
      if (tokenMatch) {
        token = tokenMatch[0];
      }
    }

    if (token) {
      console.log(`\n✅ Found authtoken: ${token.substring(0, 10)}...${token.substring(token.length - 5)}`);

      // Write to .env file
      let envContent = '';
      if (existsSync(ENV_PATH)) {
        envContent = readFileSync(ENV_PATH, 'utf-8');
        // Replace existing NGROK_AUTHTOKEN if present
        if (envContent.includes('NGROK_AUTHTOKEN=')) {
          envContent = envContent.replace(/NGROK_AUTHTOKEN=.*/g, `NGROK_AUTHTOKEN=${token}`);
        } else {
          envContent += `\nNGROK_AUTHTOKEN=${token}`;
        }
      } else {
        envContent = `# TMNL Docker Stack Environment Variables\n# Generated by get-ngrok-token.mjs\n\nNGROK_AUTHTOKEN=${token}\n`;
      }

      writeFileSync(ENV_PATH, envContent);
      console.log(`📝 Written to ${ENV_PATH}`);
    } else {
      console.log('\n❌ Could not find authtoken automatically.');
      console.log('   Please copy it manually from the browser and add to docker/.env');
      console.log('   Press Enter to close the browser...');
      await new Promise(resolve => process.stdin.once('data', resolve));
    }

  } catch (error) {
    console.error('❌ Error:', error.message);
  } finally {
    await browser.close();
  }
}

main().catch(console.error);
